using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;
[InitializeOnLoad]public static class CoffeeFloorRestore{static CoffeeFloorRestore(){EditorApplication.delayCall+=Restore;}static void Restore(){if(!File.Exists("CoffeeFloorRestore.request"))return;File.Delete("CoffeeFloorRestore.request");if(EditorApplication.isCompiling){EditorApplication.delayCall+=Restore;return;}try{var sc=SceneManager.GetActiveScene();var layouts=sc.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<CityGroundTextureLayout>(true)).ToArray();foreach(var l in layouts){foreach(var p in l.plots.Where(p=>(p.data.x==2||p.data.x==4)&&p.renderer)){var c=p.renderer.bounds.center;var delta=new Vector2(c.x-p.rect.x,c.z-p.rect.y);p.rect.x=c.x;p.rect.y=c.z;p.feature0.x+=delta.x;p.feature0.y+=delta.y;if(p.data.x==4){p.feature0.z+=delta.y;p.feature1.x+=delta.x;}for(int i=0;i<p.patches.Length;i++){p.patches[i].x+=delta.x;p.patches[i].y+=delta.y;}}l.Apply();EditorUtility.SetDirty(l);PrefabUtility.RecordPrefabInstancePropertyModifications(l);}File.WriteAllLines("FinalEnvironmentRoadReview/CoffeeFloorAudit.txt",layouts.SelectMany(l=>l.plots).Where(p=>p.data.x==2).Select(p=>p.renderer.name+" material="+p.renderer.sharedMaterial.name+" shader="+p.renderer.sharedMaterial.shader.name+" rect="+p.rect+" data="+p.data+" patches="+string.Join(";",p.patches.Select(v=>v.ToString()))));var plots=layouts.SelectMany(l=>l.plots).Where(p=>(p.data.x==2||p.data.x==4)&&p.renderer).ToArray();if(plots.Length!=3)throw new Exception("Expected two cafes and hospital, found "+plots.Length);var ctrl=sc.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<CityDayNightController>(true)).First();bool night=ctrl.IsNight;try{ctrl.Apply(false);int n=0;foreach(var p in plots){var c=p.renderer.bounds.center;CityLightingBuilder.Capture(ctrl,Tuple.Create(c+(p.data.x==4?new Vector3(70,40,0):new Vector3(0,65,55)),Quaternion.LookRotation(p.data.x==4?new Vector3(-70,-40,0):new Vector3(0,-65,-55))),"Coffee-Floor-Restored-"+(++n));}}finally{ctrl.Apply(night);}EditorSceneManager.MarkSceneDirty(sc);EditorSceneManager.SaveScene(sc);File.WriteAllText("FinalEnvironmentRoadReview/CoffeeFloorRestore.txt","SUCCESS restored existing serialized floor/seating layout property blocks at both coffee shops. No furniture, transforms, source meshes, lighting or materials changed. Plots="+plots.Length+" patches="+string.Join(",",plots.Select(p=>p.data.z)));}catch(Exception e){File.WriteAllText("FinalEnvironmentRoadReview/CoffeeFloorRestore.txt",e.ToString());}}}
